  str_n38_hard_name_3 = "H3 - Mastro e Remo",
  str_n38_hard_name_4 = "H4 - Remos Virados",
  str_n38_hard_desc_1 = "Recifes não sinalizados estão escondidos nas águas à frente. Diminua a velocidade para identificar seu caminho com cuidado.",
  str_n38_hard_desc_2 = "Um vendaval começa a soprar no mar. Aperte rapidamente as cordas das velas para estabilizar o navio.",
  str_n38_hard_desc_3 = "Uma onda enorme está vindo em sua direção. Proteja todas as instalações no convés rapidamente.",
  str_n38_hard_desc_4 = "Um penhasco íngreme apareceu repentinamente no fundo do mar. Vire imediatamente para não colidir com ele e danificar seu navio.",
  str_n38_0_levelname_EX = "Navio Perdido no Mar (Naufragado)",
  str_n38_1_levelname_EX = "EX1 - Ondas Furiosas",
  str_n38_2_levelname_EX = "EX2 - Mares Tempestuosos",
