  str_n38_1_levelname_EX1 = "EX1-1 - Ondas Furiosas: Redemoinho",
  str_n38_1_levelname_EX2 = "EX1-2 - Ondas Furiosas: Contra as Rochas",
  str_n38_2_levelname_EX1 = "EX2-1 - Mares Tempestuosos: Corrente Turbulenta",
  str_n38_2_levelname_EX2 = "EX2-2 - Mares Tempestuosos: Surto",
  str_n38_3_levelname_EX1 = "EX3-1 - Maré Fervente: Torrente Jorrante",
  str_n38_3_levelname_EX2 = "EX3-2 - Maré Fervilhante: Águas Desesperadas",
  str_n38_3_levelname_EX3 = "EX3-3 - Maré Fervente: Sem Limites",
